static std::vector<U8> blob(bool vertex){
    const std::string metadata=std::string("{\"parameters\":{},\"input_semantics\":")+(vertex?"[[0,0,0]]":"[]")+",\"reflection\":{\"ubos\":"+(vertex?"[]":"[{\"binding\":13,\"block_size\":16,\"name\":\"BlurPCAlphaTestState\"}]")+"}}";
    const std::string source=std::string("#include <metal_stdlib>\nusing namespace metal;\n")+(vertex?"struct I{float2 p[[attribute(0)]];};vertex float4 blur_main(I i[[stage_in]]){return float4(i.p,.5,1);}":"struct Alpha{uint enabled,function;float reference;uint format;};fragment float4 blur_main(constant Alpha& a[[buffer(13)]]){if(a.enabled&&(a.function==1||(a.function==5&&.5<=a.reference)))discard_fragment();return float4(.25,.5,.75,.5);}");
    const std::string entry="blur_main";std::vector<U8> b(40);std::memcpy(b.data(),"BMSL",4);auto word=[&](U32 p,U32 n){for(U32 i=0;i<4;++i)b[p+i]=U8(n>>(8*i));};word(4,1);word(8,vertex?0:1);word(16,40);word(20,metadata.size());word(24,40+metadata.size());word(28,source.size());word(32,40+metadata.size()+source.size());word(36,entry.size());b.insert(b.end(),metadata.begin(),metadata.end());b.insert(b.end(),source.begin(),source.end());b.insert(b.end(),entry.begin(),entry.end());word(12,b.size());return b;
}
static void pixels(Display2::C_Surface& target,U32 expected,U32 tolerance=0){auto lock=target.LockRect(16);require(lock.pBits,"Blend sentinel GPU readback unavailable");bool correct=true;for(U32 y=0;y<target.GetHeight();++y)for(U32 x=0;x<target.GetWidth();++x){U32 actual;std::memcpy(&actual,lock.pBits+y*lock.pitch+x*4,4);for(U32 c=0;c<4;++c){const int a=(actual>>(c*8))&255,e=(expected>>(c*8))&255;correct&=std::abs(a-e)<=int(tolerance);}}target.UnlockRect();require(correct,"Blend sentinel changed actual GPU blend/alpha/write state");}
template<class F>static void rejects(F call){bool failed=false;try{call();}catch(const std::logic_error& e){failed=std::string(e.what()).find("blend mode ")!=std::string::npos;}require(failed,"Unsupported blend enumerator lacked a numeric diagnostic");}
int main(){try{
    ProbeDevice device;device.SetBlendMode(Display::E_BlendMode_Unknown);require(device.GetBlendMode()==Display::E_BlendMode_Unknown,"Original uncreated device sentinel touched GPU state");Display::C_DeviceParams params;params.m_Width=19;params.m_Height=11;require(device.Create(params)&&device.CreateVolatile(params),"Blend sentinel native device creation failed");auto& native=device.GetDisplay2();auto& c=native.GetContext();Display2::C_VertexShader vs;Display2::C_PixelShader ps;auto v=blob(true),p=blob(false);std::string error;require(native.CreateVertexShader(v.size(),v.data(),0,&vs,nullptr,&error),error.c_str());require(native.CreatePixelShader(p.size(),p.data(),0,&ps,nullptr,&error),error.c_str());Display2::C_VertexDeclaration declaration;Display2::C_VertexFormat format;format.AddElement(0,0,Display2::E_VertexElementType_F32_2,Display2::E_VertexElementUsage_Position,0);Display2::C_VertexBuffer vertices;require(native.CreateVertexDeclaration(format,&declaration)&&native.CreateVertexBuffer(32,0,&vertices),"Blend sentinel real geometry creation failed");const F32 quad[]={-1,1,1,1,-1,-1,1,-1};auto out=vertices.Lock();require(out,"Blend sentinel geometry map failed");std::memcpy(out,quad,sizeof(quad));vertices.Unlock();
    require(device.BeginScene(),"Blend sentinel scene failed");device.SetLuminanceWrite(Display::E_LuminanceWrite_Enabled);
    for(U32 value=0;value<Display::E_BlendMode_Count;++value){if(value==Display::E_BlendMode_SolidAlphaMask)continue;device.SetBlendMode(Display::E_BlendMode(value));auto before=device.states();const auto blend=c.GetBlendState().m_BlendBits,alpha=c.GetAlphaTestState().m_AlphaTestBits;device.SetBlendMode(Display::E_BlendMode_Unknown);device.SetBlendMode(Display::E_BlendMode_Unknown);require(device.states()==before&&c.GetBlendState().m_BlendBits==blend&&c.GetAlphaTestState().m_AlphaTestBits==alpha&&device.GetBlendMode()==Display::E_BlendMode_Unknown,"Unknown sentinel mutated a PC mode or real native state");}
    for(auto invalid:{Display::E_BlendMode_Count,Display::E_BlendMode_SolidAlphaMask,Display::E_BlendMode(14),Display::E_BlendMode(15)})rejects([&]{device.SetBlendMode(invalid);});device.EndScene();
    auto setup=[&]{require(device.BeginScene(),"Blend sentinel GPU scene failed");device.SetLuminanceWrite(Display::E_LuminanceWrite_Enabled);c.SetVertexShader(&vs);c.SetPixelShader(&ps);c.SetVertexBuffer(0,&vertices,0,8,&declaration);device.SetDepthEnable(Display::E_Bool_False);device.SetCullMode(Display::E_CullMode_None);c.Clear(Display2::E_Clear_Colour,0x40102030);};
    for(U32 sentinel=0;sentinel<2;++sentinel){setup();device.SetAlphaTestEnable(Display::E_Bool_True);device.SetAlphaTestFunc(Display::E_CmpFunc_Greater);device.SetAlphaTestRef(0);device.SetBlendEnable(Display::E_Bool_True);device.SetBlend(Display::E_Blend_SrcAlpha,Display::E_Blend_One,Display::E_BlendOp_Add,Display::E_Blend_One,Display::E_Blend_Zero,Display::E_BlendOp_Add);device.SetColourWriteEnable(Display::E_ColourWriteEnable_All);auto before=device.states();if(sentinel)device.SetBlendMode(Display::E_BlendMode_Unknown);require(before==device.states(),"Extended UI Unknown altered upper cached state");c.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);device.EndScene();pixels(*device.GetNativeColourSurface(),0x80306090,1);}
    setup();device.SetAlphaTestEnable(Display::E_Bool_True);device.SetAlphaTestFunc(Display::E_CmpFunc_Greater);device.SetAlphaTestRef(191);device.SetBlendEnable(Display::E_Bool_False);device.SetColourWriteEnable(Display::E_ColourWriteEnable_All);device.SetBlendMode(Display::E_BlendMode_Unknown);c.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);device.EndScene();pixels(*device.GetNativeColourSurface(),0x40102030);
    setup();device.SetAlphaTestEnable(Display::E_Bool_True);device.SetAlphaTestFunc(Display::E_CmpFunc_Never);device.SetBlendEnable(Display::E_Bool_True);device.SetColourWriteEnable(Display::E_ColourWriteEnable_All);device.SetBlendMode(Display::E_BlendMode_Default);require(device.GetBlendMode()==Display::E_BlendMode_Default&&device.states()[0]==Display::E_Bool_False&&device.states()[3]==Display::E_Bool_False&&device.states()[10]==7,"Default did not apply original PC alpha/blend/RGB write selection");c.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);device.EndScene();pixels(*device.GetNativeColourSurface(),0x404080bf);
    {Display::C_Context context;context.m_Context.Bind(native);for(auto mode:{Display::E_BlendMode_Default,Display::E_BlendMode_Unknown}){setup();device.SetAlphaTestEnable(Display::E_Bool_True);device.SetAlphaTestFunc(Display::E_CmpFunc_Never);device.SetBlendEnable(Display::E_Bool_True);device.SetBlend(Display::E_Blend_Zero,Display::E_Blend_One,Display::E_BlendOp_Subtract,Display::E_Blend_Zero,Display::E_Blend_Zero,Display::E_BlendOp_Subtract);device.SetColourWriteEnable(Display::E_ColourWriteEnable_All);context.SetBlendMode(mode);Display2::C_BlendState b;Display2::C_AlphaTestState a;require(c.GetBlendState().m_BlendBits==b.m_BlendBits&&c.GetAlphaTestState().m_AlphaTestBits==a.m_AlphaTestBits,"Shared context sentinel did not preserve its original default-factor behavior");c.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);device.EndScene();pixels(*device.GetNativeColourSurface(),0xc04080bf,1);}for(auto invalid:{Display::E_BlendMode_Count,Display::E_BlendMode_SolidAlphaMask,Display::E_BlendMode(14)})rejects([&]{context.SetBlendMode(invalid);});}
    // [Blur2PC][macOS] Upper Context owns the PC Default policy; lower masks remain literal.
    {Display::C_Context context;context.m_Context.Bind(native);
        constexpr U32 clear=0x40102030,drawn=0x804080bf;
        auto expected=[&](U32 mask){U32 result=clear;const U32 bits[]={4,2,1,8};for(U32 byte=0;byte<4;++byte)if(mask&bits[byte])result=(result&~(255U<<(byte*8)))|(drawn&(255U<<(byte*8)));return result;};
        auto maskDraw=[&](U32 requested,U32 resolved,bool indexed){setup();device.SetAlphaTestEnable(Display::E_Bool_False);device.SetBlendEnable(Display::E_Bool_False);device.SetColourWriteEnable(Display::E_ColourWriteEnable_All);if(indexed)context.SetColourWriteEnable(0,requested);else context.SetColourWriteEnable(requested);require(device.states()[10]==resolved&&context.GetColourWriteEnable(0)==resolved,"Upper Context mask lost device default/cache policy");c.DrawPrimitive(Display2::E_PrimitiveType_TriangleStrip,0,4);device.EndScene();pixels(*device.GetNativeColourSurface(),expected(resolved),1);};
        for(U32 mask=0;mask<16;++mask){maskDraw(mask,mask,false);maskDraw(mask,mask,true);}
        for(U32 selected:{7U,8U,0U,15U}){device.colourDefault(selected);maskDraw(Display::E_ColourWriteEnable_Default,selected,false);maskDraw(Display::E_ColourWriteEnable_Default,selected,true);}
        device.colourDefault(7);
        setup();device.SetColourWriteEnable(5);const auto before=device.states();
        for(U32 invalid:{16U,0x80000000U,0xfffffffeU})for(bool indexed:{false,true}){bool rejected=false;try{if(indexed)context.SetColourWriteEnable(0,invalid);else context.SetColourWriteEnable(invalid);}catch(const std::logic_error&){rejected=true;}require(rejected&&device.states()==before&&context.GetColourWriteEnable(0)==5,"Invalid upper mask changed state or bypassed lower validation");}
        bool badTarget=false;try{context.SetColourWriteEnable(4,Display::E_ColourWriteEnable_Default);}catch(const std::logic_error&){badTarget=true;}require(badTarget&&device.states()==before,"Invalid MRT mask target changed cached state");
        bool literalDefault=false;try{c.SetColourWriteEnable(Display::E_ColourWriteEnable_Default);}catch(const std::logic_error&){literalDefault=true;}require(literalDefault&&device.states()==before,"Lower literal mask incorrectly accepted upper Default policy");
        device.EndScene();
    }
    native.Destroy(&vertices);native.Destroy(&declaration);native.Destroy(&vs);native.Destroy(&ps);require(native.WaitIdle(),"Blend sentinel GPU completion failed");device.DestroyVolatile();device.Destroy();std::cout<<"Original PC device Unknown invalidation preserves all modes and actual extended-UI blend/alpha-test GPU pixels; Default applies PC disabled-alpha/blend RGB-write behavior; shared context retains original distinct default-factor behavior; invalid modes have numeric diagnostics; scalar/indexed Context all16 masks and actual per-device Default have GPU/readiness/cache/rejection coverage PASS\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
